<!doctype html><html lang="id" data-theme="light"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Masuk · SIMANTAP</title><link rel="stylesheet" href="assets/css/icons.min.css"><link rel="stylesheet" href="assets/css/app.css"><style>.auth-page{min-height:100vh;display:grid;place-items:center;padding:24px;background:var(--ground)}.auth-card{width:min(100%,430px);background:var(--surface);border:1px solid var(--border);border-radius:18px;padding:34px;box-shadow:0 18px 50px rgba(32,44,64,.1)}.auth-brand{text-align:center;margin-bottom:28px}.auth-brand .brand-mark{margin:0 auto 15px}.auth-brand h1{font-size:25px;font-weight:800;margin:0}.auth-brand h1 span{color:var(--primary)}.auth-brand p{font-size:12px;color:var(--muted)}.auth-card label{display:block;font-size:11px;font-weight:800;margin-top:16px}.auth-input{height:44px;display:flex;align-items:center;gap:9px;border:1px solid var(--border);border-radius:9px;margin-top:7px;padding:0 12px}.auth-input input{border:0;outline:0;background:none;flex:1;color:var(--ink)}.auth-card .primary-button{width:100%;margin-top:22px}.auth-error{padding:10px 12px;border-radius:8px;background:var(--rose-bg);color:var(--rose);font-size:11px;margin-bottom:13px}.auth-secure{text-align:center;font-size:9px;color:var(--muted);margin-top:22px;padding-top:18px;border-top:1px solid var(--border)}</style></head><body><main class="auth-page"><section class="auth-card"><div class="auth-brand"><span class="brand-mark"><i class="ri-mail-send-line"></i></span><h1>Masuk ke SIMANTAP<span>.</span></h1><p>Gunakan akun resmi Universitas Muhammadiyah Ponorogo</p></div><?php if(!empty($loginError)): ?><div class="auth-error" role="alert"><?= e($loginError) ?></div><?php endif; ?><form action="?page=login" method="post"><input type="hidden" name="_token" value="<?= e(Security::csrfToken()) ?>"><label>Username / Email / NIP<div class="auth-input"><i class="ri-user-3-line"></i><input name="username" autocomplete="username" placeholder="Masukkan identitas akun" required autofocus></div></label><label>Kata Sandi<div class="auth-input"><i class="ri-lock-2-line"></i><input type="password" name="password" autocomplete="current-password" placeholder="Masukkan kata sandi" required></div></label><button class="primary-button" type="submit">Masuk ke Sistem <i class="ri-arrow-right-line"></i></button></form><div class="auth-secure"><i class="ri-shield-check-line"></i> Portal resmi, aman, dan tercatat dalam audit log</div></section></main></body></html>
